<?php

declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Integration\CustomerPolicy;
use CetechDeliveryEngine\Infrastructure\Persistence\{CustomerPolicyReceiptStore as Store,CustomerPolicyReceiptUnit as Unit,CustomerPolicyReceiptStorageException};
use CetechDeliveryEngine\Infrastructure\WordPress\OperationConnectionMysqliTransport;
use CetechDeliveryEngine\Tests\Support\CustomerPolicy\CustomerPolicyProofTransport;
use CetechDeliveryEngine\Tests\Support\Operation\OperationProofDatabase as DB;
use PHPUnit\Framework\Attributes\Group;
use PHPUnit\Framework\TestCase;
/** Actual dedicated MariaDB owners, native options metadata and physical COMMIT outcomes. */
#[Group('rule-lifecycle-real-db')]
final class CustomerPolicyReceiptRealDatabaseTest extends TestCase {
 private \mysqli $db; private string $prefix; private array $transports=[]; private string $subject; private string $attempt='11111111-1111-4111-8111-111111111111';
 protected function setUp():void{$this->db=DB::connect();$this->prefix=DB::prefix();DB::install($this->db,$this->prefix);$this->subject=str_repeat('a',64);}
 protected function tearDown():void{foreach($this->transports as$t)$t->force_close();if(isset($this->db,$this->prefix)){DB::execute($this->db,"ALTER TABLE `{$this->prefix}options` ENGINE=InnoDB");DB::cleanup($this->db,$this->prefix);$this->db->close();}}
 private function store(?callable$configure=null):Store{return new Store(1,$this->prefix,function()use($configure){$native=OperationConnectionMysqliTransport::connect((string)(getenv('CETECH_DE_REAL_DB_HOST')?:'127.0.0.1'),(string)(getenv('CETECH_DE_REAL_DB_USER')?:'root'),(string)(getenv('CETECH_DE_REAL_DB_PASSWORD')?:''),(string)getenv('CETECH_DE_REAL_DB_NAME'),(int)(getenv('CETECH_DE_REAL_DB_PORT')?:3306));$t=new CustomerPolicyProofTransport($native);$this->transports[]=$t;if(null!==$configure)$configure($t);return$t;});}
 private function rows():array{$r=$this->db->query("SELECT option_id,option_name,option_value,autoload FROM `{$this->prefix}options` WHERE option_name LIKE 'cetech!_de!_customer!_policy!_%' ESCAPE '!' ORDER BY option_id");if(!$r instanceof \mysqli_result)throw new \RuntimeException();return$r->fetch_all(MYSQLI_ASSOC);}
 private function refusal(callable$work):CustomerPolicyReceiptStorageException{try{$work();}catch(CustomerPolicyReceiptStorageException$e){return$e;}self::fail('Unconfirmed or unsupported owner published success.');}
 private function handoff(Store$s,string$cart='cart café 東京',string$original='original immutable'):array{return$s->transaction($this->subject,function(Unit$u)use($cart,$original){return['cart'=>$u->put_cart(null,$cart),'original'=>$u->put_original($this->attempt,null,$original)];});}
 private function witness(array$rows,?array$index=null):array{return['site_id'=>1,'prefix'=>$this->prefix,'subject'=>$this->subject,'attempt_id'=>$this->attempt,'cart'=>$rows['cart'],'original'=>$rows['original'],'order_index'=>$index];}
 public function test_cart_and_complete_original_commit_atomically_with_exact_unicode_bytes():void{$rows=$this->handoff($this->store());self::assertCount(2,$this->rows());self::assertSame('cart café 東京',$rows['cart']['bytes']);self::assertSame('off',$rows['cart']['autoload']);self::assertSame('original immutable',$rows['original']['bytes']);$t=end($this->transports);self::assertSame(1,$t->sent_commits);self::assertTrue($t->closed);self::assertTrue($this->store()->transaction($this->subject,fn(Unit$u):bool=>Store::verify_witness($u->session(),$this->witness($rows))));}
 public function test_two_guest_subjects_have_independent_physical_rows_and_locks():void{$this->handoff($this->store());$other=str_repeat('b',64);$row=$this->store()->transaction($other,fn(Unit$u)=>$u->put_cart(null,'independent guest'));self::assertNotSame(Store::cart_name(1,$this->subject),$row['option_name']);self::assertCount(3,$this->rows());self::assertSame('independent guest',$row['bytes']);}
 public function test_same_bytes_delete_reinsert_cannot_revive_an_old_physical_row_handle():void{$old=$this->handoff($this->store());$name=$old['cart']['option_name'];DB::execute($this->db,"DELETE FROM `{$this->prefix}options` WHERE option_id=".$old['cart']['row_id']);DB::option($this->db,$this->prefix,$name,$old['cart']['bytes']);self::assertFalse($this->store()->transaction($this->subject,fn(Unit$u):bool=>Store::verify_witness($u->session(),$this->witness($old))));self::assertCount(2,$this->rows());}
 public function test_existing_autoload_is_preserved_and_case_folded_option_names_are_not_authority():void{$old=$this->handoff($this->store());DB::execute($this->db,"UPDATE `{$this->prefix}options` SET autoload='yes' WHERE option_id=".$old['cart']['row_id']);$new=$this->store()->transaction($this->subject,function(Unit$u){$row=$u->cart();return$u->put_cart($row,'changed bytes');});self::assertSame('yes',$new['autoload']);DB::execute($this->db,"UPDATE `{$this->prefix}options` SET option_name=UPPER(option_name) WHERE option_id=".$new['row_id']);$this->refusal(fn()=>$this->store()->transaction($this->subject,fn(Unit$u)=>$u->cart()));self::assertSame('changed bytes',array_values(array_filter($this->rows(),fn($r)=>(int)$r['option_id']===$new['row_id']))[0]['option_value']);}
 public function test_subject_lock_is_nonwaiting_and_does_not_release_another_owner():void{$db=DB::connect();$name='cetech_cp_'.substr(hash('sha256',(string)getenv('CETECH_DE_REAL_DB_NAME').':'.$this->prefix.':1:'.$this->subject),0,48);try{self::assertSame('1',DB::scalar($db,"SELECT GET_LOCK('{$name}',0)"));$called=false;$start=microtime(true);$this->refusal(function()use(&$called){return$this->store()->transaction($this->subject,function()use(&$called){$called=true;});});self::assertFalse($called);self::assertLessThan(1.5,microtime(true)-$start);self::assertSame((string)$db->thread_id,(string)DB::scalar($this->db,"SELECT IS_USED_LOCK('{$name}')"));}finally{$db->query("SELECT RELEASE_LOCK('{$name}')");$db->close();}}
 public function test_both_rows_roll_back_when_callback_fails_after_the_handoff_writes():void{$this->refusal(fn()=>$this->store()->transaction($this->subject,function(Unit$u){$u->put_cart(null,'must roll back');$u->put_original($this->attempt,null,'must also roll back');throw new \RuntimeException('owned callback failure');}));self::assertSame([],$this->rows());self::assertTrue(end($this->transports)->closed);}
 public function test_proven_unsent_commit_rolls_back_both_rows_then_original_retry_commits_once():void{$fault=$this->store(static function(CustomerPolicyProofTransport$t){$t->commit_fault='unsent';});$error=$this->refusal(fn()=>$this->handoff($fault));self::assertSame('not_sent',$error->outcome);self::assertSame([],$this->rows());self::assertSame(0,$this->transports[0]->sent_commits);$this->handoff($this->store());self::assertCount(2,$this->rows());}
 public function test_lost_commit_ack_is_unconfirmed_and_a_fresh_owner_reads_both_exact_original_rows():void{$fault=$this->store(static function(CustomerPolicyProofTransport$t){$t->commit_fault='lost_ack';});$error=$this->refusal(fn()=>$this->handoff($fault));self::assertSame('outcome_unknown',$error->outcome);self::assertCount(2,$this->rows());$fresh=$this->store()->transaction($this->subject,fn(Unit$u)=>['cart'=>$u->cart(),'original'=>$u->original($this->attempt)]);self::assertSame('cart café 東京',$fresh['cart']['bytes']);self::assertSame('original immutable',$fresh['original']['bytes']);self::assertSame(1,$this->transports[0]->sent_commits);}
 public function test_failed_retirement_never_publishes_success_even_after_actual_commit():void{$fault=$this->store(static function(CustomerPolicyProofTransport$t){$t->fail_retire=true;});self::assertSame('outcome_unknown',$this->refusal(fn()=>$this->handoff($fault))->outcome);self::assertCount(2,$this->rows());self::assertTrue($this->transports[0]->closed);}
 public function test_nontransactional_native_options_refuse_before_any_callback_or_write():void{DB::execute($this->db,"ALTER TABLE `{$this->prefix}options` ENGINE=MyISAM");$called=false;$this->refusal(function()use(&$called){return$this->store()->transaction($this->subject,function()use(&$called){$called=true;});});self::assertFalse($called);self::assertSame([],$this->rows());}
 public function test_prefix_unique_key_cannot_replace_complete_native_option_name_identity():void{DB::execute($this->db,"ALTER TABLE `{$this->prefix}options` DROP INDEX option_name, ADD UNIQUE KEY option_name(option_name(100))");$called=false;$this->refusal(function()use(&$called){return$this->store()->transaction($this->subject,function()use(&$called){$called=true;});});self::assertFalse($called);self::assertSame([],$this->rows());}
 public function test_exact_cart_byte_bound_and_plus_one_refusal_preserve_existing_original():void{$old=$this->handoff($this->store(),str_repeat('a',Store::CART_MAX_BYTES));self::assertSame(Store::CART_MAX_BYTES,strlen($old['cart']['bytes']));$before=$this->rows();$this->refusal(fn()=>$this->store()->transaction($this->subject,fn(Unit$u)=>$u->put_cart($u->cart(),str_repeat('b',Store::CART_MAX_BYTES+1))));self::assertSame($before,$this->rows());}
 public function test_native_witness_holds_exact_options_metadata_against_a_different_owner_ddl():void{$rows=$this->handoff($this->store());$other=DB::connect();try{$other->query('SET SESSION lock_wait_timeout=1');$held=$this->store()->transaction($this->subject,function(Unit$u)use($rows,$other){self::assertTrue(Store::verify_witness($u->session(),$this->witness($rows)));$ok=$other->query("ALTER TABLE `{$this->prefix}options` COMMENT='owned-mdl-test'");self::assertFalse($ok);self::assertSame(1205,$other->errno);return true;});self::assertTrue($held);self::assertTrue($other->query("ALTER TABLE `{$this->prefix}options` COMMENT='owned-after-retirement'"));}finally{$other->close();}}
 public function test_seeded_order_index_is_proved_on_same_owner_and_same_bytes_reinsert_is_stale():void{$rows=$this->handoff($this->store());$name=Store::order_index_name(1,77);DB::option($this->db,$this->prefix,$name,'seeded index bytes');$index=$this->store()->transaction($this->subject,fn(Unit$u)=>$u->order_index(77));self::assertTrue($this->store()->transaction($this->subject,fn(Unit$u)=>Store::verify_witness($u->session(),$this->witness($rows,$index))));DB::execute($this->db,"DELETE FROM `{$this->prefix}options` WHERE option_id=".$index['row_id']);DB::option($this->db,$this->prefix,$name,'seeded index bytes');self::assertFalse($this->store()->transaction($this->subject,fn(Unit$u)=>Store::verify_witness($u->session(),$this->witness($rows,$index))));}
 public function test_foreign_seeded_index_body_is_never_repaired_by_read_or_witness_failure():void{$rows=$this->handoff($this->store());$name=Store::order_index_name(1,78);DB::option($this->db,$this->prefix,$name,'foreign unknown bytes');$before=$this->rows();$index=$this->store()->transaction($this->subject,fn(Unit$u)=>$u->order_index(78));self::assertSame('foreign unknown bytes',$index['bytes']);$forged=$this->witness($rows,$index);$forged['order_index']['bytes']='pretended original';self::assertFalse($this->store()->transaction($this->subject,fn(Unit$u)=>Store::verify_witness($u->session(),$forged)));self::assertSame($before,$this->rows());}
}
